// Command gen reads a catalog file of format 1 and writes the Go file of its values and handles.
//
//	gen -import core|ecr -in FILE.catalog.json -out FILE.go [-registry DIR]
//
// -import, -in and -out are required. With -registry DIR, which holds systems.tsv and kinds.tsv of the ecd-id registry,
// the catalog's system must be a live system of the registry and each of its kinds a live entity kind of that system; a
// detached catalog is refused. Without it nothing is checked against a registry. Exit 0: FILE.go holds the generated bytes; a file that holds them already is not
// rewritten. Exit 1: the catalog is refused, by its own checks or by the registry; each refusal is printed to stderr and nothing is
// written. Exit 2: a usage error. Exit 3: a read or write error, including a registry that cannot be read or parsed
// ("gen: registry: ..."); FILE.go is as it was.
package main

import (
	"bytes"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"

	eid "github.com/fiberfx/ecd-id/go"
	"github.com/fiberfx/ecd-runtime/go/internal/gen"
)

func main() { os.Exit(run(os.Args[1:], os.Stderr)) }

// run is the command: it returns the exit code and writes every message to stderr.
func run(args []string, stderr io.Writer) int {
	fs := flag.NewFlagSet("gen", flag.ContinueOnError)
	fs.SetOutput(stderr)
	imp := fs.String("import", "", "import mode of the generated file: core or ecr")
	in := fs.String("in", "", "catalog file")
	out := fs.String("out", "", "generated Go file")
	regDir := fs.String("registry", "", "directory of the ecd-id registry (systems.tsv and kinds.tsv): check the catalog against it")
	if err := fs.Parse(args); err != nil {
		return 2
	}
	if fs.NArg() != 0 {
		fmt.Fprintf(stderr, "gen: unexpected argument %q\n", fs.Arg(0))
		fs.Usage()
		return 2
	}
	if *imp == "" || *in == "" || *out == "" {
		fmt.Fprintln(stderr, "gen: -import, -in and -out are all required")
		fs.Usage()
		return 2
	}
	mode, err := gen.ParseMode(*imp)
	if err != nil {
		fmt.Fprintf(stderr, "gen: %v\n", err)
		fs.Usage()
		return 2
	}
	src, err := os.ReadFile(*in)
	if err != nil {
		fmt.Fprintf(stderr, "gen: %v\n", err)
		return 3
	}
	var reg *eid.Registry
	if *regDir != "" {
		if reg, err = readRegistry(*regDir); err != nil {
			fmt.Fprintf(stderr, "gen: registry: %v\n", err)
			return 3
		}
	}
	got, err := gen.GenerateWith(src, filepath.Base(*in), mode, reg)
	if err != nil {
		var refused *gen.Refused
		if errors.As(err, &refused) {
			fmt.Fprintln(stderr, refused.Error())
			return 1
		}
		fmt.Fprintf(stderr, "gen: %v\n", err)
		return 3
	}
	if err := write(*out, got); err != nil {
		fmt.Fprintf(stderr, "gen: %v\n", err)
		return 3
	}
	return 0
}

// readRegistry reads systems.tsv and kinds.tsv of dir and parses them.
func readRegistry(dir string) (*eid.Registry, error) {
	systems, err := os.ReadFile(filepath.Join(dir, "systems.tsv"))
	if err != nil {
		return nil, err
	}
	kinds, err := os.ReadFile(filepath.Join(dir, "kinds.tsv"))
	if err != nil {
		return nil, err
	}
	return eid.ParseRegistry(string(systems), string(kinds))
}

// write puts b in the file at path through a temporary file in the same directory, so a failure leaves the file as it
// was. A file that holds b already is not rewritten; an absent file never counts as equal, even to an empty b.
func write(path string, b []byte) error {
	if old, err := os.ReadFile(path); err == nil && bytes.Equal(old, b) {
		return nil
	}
	f, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+".*")
	if err != nil {
		return err
	}
	name := f.Name()
	if _, err := f.Write(b); err != nil {
		f.Close()
		os.Remove(name)
		return err
	}
	if err := f.Close(); err != nil {
		os.Remove(name)
		return err
	}
	if err := os.Chmod(name, 0o644); err != nil {
		os.Remove(name)
		return err
	}
	if err := os.Rename(name, path); err != nil {
		os.Remove(name)
		return err
	}
	return nil
}
